  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mermadehair.com/blogs/work-with-us', 'official_site', 'affiliate', 'Mermade Hair''s own Work With Us page describes its affiliate programme: powered by Refersion, affiliates earn a 15% commission when a customer shops with their unique code or link, customers receive 15% off, payments are automatic via PayPal, and milestone rewards are paid at $10K, $50K and $100K in sales. No earnings-cap statement appears, so the cap is unknown.', 'verified', now());
