  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://help.going.com/hc/en-us/articles/26875867320212-Referral-Program-FAQ', 'official_site', 'affiliate', 'Going''s official help-center FAQ (fetched) confirms a separate Affiliate Program for people with large audiences: ''If you have a big audience, why not apply for our Affiliate Program? You can earn a commission for promoting Going on your social channels or website.'' (The page''s 10-per-year cap applies only to the consumer referral gift-card scheme, not the affiliate program.)', 'verified', now());
