  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 10, 8, 6, 4, '{"compensation": "The program pays flat per-member bounties, but published figures conflict ($3 per sign-up vs $10 Premium/$40 Elite vs 50% of fee), so the rate is null; the underlying memberships cost $49-$199/yr.", "contact_access": "The official help center points large-audience creators to the affiliate application; no public partnerships email found \u2014 mid-range.", "credibility": "Founded 2015 as Scott''s Cheap Flights; a widely cited flight-deal service with 2M+ members, though smaller than the OTAs.", "niche_fit": "Flight-deal and mistake-fare content performs strongly with travel creators and deal communities.", "opportunity_availability": "Application-based and aimed at creators with large audiences, per Going''s own FAQ \u2014 more selective than open network programs.", "ugc_evidence": "Going explicitly recruits social-channel promoters for the affiliate program, separate from its consumer referral scheme."}'::jsonb);
