  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getfknnuts.com/pages/affiliate-program.', 'https://getfknnuts.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FKN Nuts Heat Squad Creator Program (Shopify Collabs)', 'https://getfknnuts.com/pages/affiliate-program', 'https://getfknnuts.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getfknnuts.com/pages/affiliate-program', 'official_site', 'affiliate', 'FKN Nuts'' own affiliate page (fetched) runs applications through Shopify Collabs: creators start at 10% commission on bundles and single bags, climbing lifetime-order tiers to 12% (10 orders), 15% (50 orders) and 20% (150 orders), plus up to $425 in cash bonuses and a free starter box. The page''s ''How much can I earn?'' answer lists rates and bonuses only — no statement about a cap on total earnings, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getfknnuts.com/pages/affiliate-program', 'official_site', 'ugc_collab', 'The program is explicitly creator-first: streamers, YouTube/TikTok creators, Instagram creators, podcasters and gaming communities; approved creators get a link, a 10%-off fan code, reposts on @getfknnuts and features on the brand''s socials. Eligibility is US creators aged 21+; no creator-count or cohort-size figure is published, so saturation is recorded as unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 18, 14, 10, 9, 3, '{"niche_fit": "A snack brand whose whole go-to-market is short-form creator content \u2014 taste tests, reactions and challenges \u2014 squarely in the food UGC niche.", "ugc_evidence": "A dedicated creator program with tiered perks for posting: starter boxes, monthly free boxes at higher tiers, reposts and social features.", "compensation": "10% base commission published on the brand''s own page, rising to 20% at the top lifetime tier, plus cash bonuses; no cap statement is published, so the cap stays unknown.", "contact_access": "A public application route via the official page and Shopify Collabs; no direct program email is published.", "opportunity_availability": "Applications are open to US creators 21+ of any size (''we care more about an engaged audience than follower count''), reviewed by hand within a few days.", "credibility": "Small, young DTC snack brand with a real storefront and a fully documented program page; limited track record compared with legacy brands."}'::jsonb);
