  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Goated Wellness Affiliate Program', 'https://goatedwellness.com/affiliate-program/', 'https://goatedwellness.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://goatedwellness.com/affiliate-program/', 'official_site', 'affiliate', 'Goated Wellness'' own affiliate page (fetched) states a 15% standard commission and 20% for VIP affiliates on every qualifying order, a personal 20%-off code for the audience, a 30-day referral window, and monthly Zelle payouts from the 1st with no minimum threshold. The page makes no statement about a cap on total earnings, so the cap is recorded as unknown.', 'verified', now());
