  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 15, 12, 8, 3, '{"niche_fit": "Core sports-supplement line (creatine, protein, collagen) aimed at gym and wellness creators \u2014 a strong fit for fitness UGC.", "ugc_evidence": "A structured direct affiliate program with personal codes and dashboards; less creator-content-specific than ambassador-style programs.", "compensation": "15% standard and 20% VIP rates published on the brand''s own page, with no-minimum monthly payouts; no cap statement published, so the cap stays unknown.", "contact_access": "Published program email (hello@goatedwellness.com) plus an on-site application.", "opportunity_availability": "Free to join with team review of applications; no follower minimum is stated.", "credibility": "Small DTC supplement brand with a complete, transparent program page; limited public track record."}'::jsonb);
