  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 17, 10, 7, 5, '{"niche_fit": "One of the most creator-driven supplement brands in fitness; its products are designed to be reviewed, compared and demonstrated on camera.", "ugc_evidence": "A formal ambassador program with content requirements, a welcome box, a private community and an athlete pathway \u2014 deep UGC infrastructure.", "compensation": "20% commission paid in cash on every referred sale, published on the brand''s own page; no cap statement published, so the cap stays unknown.", "contact_access": "A defined application page with published requirements and review timelines; no direct program email is published.", "opportunity_availability": "Open application but gated: 750+ followers, 20+ posts, 4+ posts/month, and a 2-4 week review.", "credibility": "Major DTC supplement brand with a ~450K-follower Instagram presence and a long-running athlete/ambassador roster."}'::jsonb);
